mapper.select:
SELECT *
FROM ai_task
WHERE user_id = #{userId}
  AND client_request_id = #{clientRequestId}
LIMIT 1

mapper.update:

UPDATE ai_task
SET status = 'QUEUED',
    queue_time = COALESCE(queue_time, #{queueTime}),
    version_id = version_id + 1
WHERE id = #{taskId}
  AND user_id = #{userId}
  AND client_request_id = #{clientRequestId}
  AND status = 'PENDING'

UPDATE ai_task
SET status = 'RETRY_WAIT',
    worker_id = NULL,
    lease_until = NULL,
    error_code = #{errorCode},
    error_message = #{errorMessage},
    version_id = version_id + 1
WHERE id = #{taskId}
  AND user_id = #{userId}
  AND client_request_id = #{clientRequestId}
  AND status = 'RUNNING'
  AND worker_id = #{workerId}
  AND version_id = #{versionId}


UPDATE ai_task
SET status = 'SUCCESS',
    ai_info_id = #{aiInfoId},
    worker_id = NULL,
    lease_until = NULL,
    error_code = NULL,
    error_message = NULL,
    finish_time = #{finishTime},
    version_id = version_id + 1
WHERE id = #{taskId}
  AND user_id = #{userId}
  AND client_request_id = #{clientRequestId}
  AND status = 'RUNNING'
  AND worker_id = #{workerId}
  AND version_id = #{versionId}

UPDATE ai_task
SET status = 'FAILED',
    worker_id = NULL,
    lease_until = NULL,
    error_code = #{errorCode},
    error_message = #{errorMessage},
    finish_time = #{finishTime},
    version_id = version_id + 1
WHERE id = #{taskId}
  AND user_id = #{userId}
  AND client_request_id = #{clientRequestId}
  AND status = 'RUNNING'
  AND worker_id = #{workerId}
  AND version_id = #{versionId}

mapper.select:
SELECT *
FROM mq_outbox
WHERE status IN ('NEW', 'RETRY_WAIT')
AND next_retry_time <= #{now}
ORDER BY next_retry_time ASC, id ASC
LIMIT #{limit}

SELECT *
FROM ai_task
WHERE status = 'RUNNING'
AND lease_until < #{now}
ORDER BY lease_until ASC
LIMIT #{limit}
